def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    sep = next(r for r, row in enumerate(g) if all(x == 2 for x in row))
    cells = [(r, c) for r in range(h) for c in range(w)
             if g[r][c] not in (2, 4)]
    if not cells:
        return g

    rows = sorted({r for r, c in cells})
    if rows[-1] < sep:
        # Object is above the separator; advance it down one row.
        source_rows, dr = rows, 1
        adjacent = rows[-1] == sep - 1
    else:
        # Object is below the separator; advance it up one row.
        source_rows, dr = rows, -1
        adjacent = rows[0] == sep + 1

    if adjacent:
        mark = rows[0] - 1 if dr == -1 else rows[-1] + 1
        if 0 <= mark < h:
            g[mark] = [8] * w
        return g

    color_cells = [(r, c, g[r][c]) for r, c in cells]
    for r, c, _ in color_cells:
        g[r][c] = 4
    for r, c, value in color_cells:
        g[r + dr][c] = value
    for r in rows:
        g[r] = [8] * w
    return g
